<?php
session_start();require_once __DIR__.'/config/database.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$ph=trim($_POST['phone']??'');$a=trim($_POST['address']??'');$city=trim($_POST['city']??'');$pw=$_POST['password']??'';if(!$n||!filter_var($e,FILTER_VALIDATE_EMAIL)||!$ph||!$a||!$city||strlen($pw)<6)$error='Please complete all fields. Password must be at least 6 characters.';else{$s=$conn->prepare("SELECT id FROM users WHERE email=?");$s->bind_param("s",$e);$s->execute();if($s->get_result()->fetch_assoc())$error='Email already registered.';else{try{$conn->begin_transaction();$h=password_hash($pw,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'user')");$s->bind_param("sss",$n,$e,$h);$s->execute();$uid=$conn->insert_id;$s=$conn->prepare("INSERT INTO clients(user_id,phone,address,city) VALUES(?,?,?,?)");$s->bind_param("isss",$uid,$ph,$a,$city);$s->execute();$cid=$conn->insert_id;$conn->commit();session_regenerate_id(true);$_SESSION['user_id']=$uid;$_SESSION['user_name']=$n;$_SESSION['user_email']=$e;$_SESSION['client_id']=$cid;header('Location:index.php');exit;}catch(Throwable $x){$conn->rollback();$error='Registration failed.';}}}}?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-page"><div class="auth-card auth-card-wide"><div class="logo">SmartStore</div><h3 class="fw-bold text-dark-custom my-4">Create Account</h3><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input class="form-control" name="name" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" required></div><div class="col-md-6"><label class="form-label">City</label><input class="form-control" name="city" required></div><div class="col-12"><label class="form-label">Address</label><input class="form-control" name="address" required></div><div class="col-12"><label class="form-label">Password</label><input class="form-control" type="password" name="password" minlength="6" required></div><div class="col-12"><button class="btn custom-primary w-100 rounded-pill">Create Account</button></div></div></form></div></body></html>